import { useEditor, EditorContent, Editor } from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'
import Image from '@tiptap/extension-image'
import TextAlign from '@tiptap/extension-text-align'
import { TextStyle } from '@tiptap/extension-text-style'
import Underline from '@tiptap/extension-underline'
import { Color } from '@tiptap/extension-color'
import { useEffect } from 'react'
import { EditorToolbar } from './EditorToolbar'
import { uploadFile } from '@/services/api'
import { useUIStore } from '@/store/useUIStore'

interface RichTextEditorProps {
    content: string
    editable?: boolean
    onUpdate: (content: string) => void
    onBlur?: () => void
    onKeyDown?: (e: KeyboardEvent) => void
    autofocus?: boolean
}

export function RichTextEditor({
    content,
    onUpdate,
    onBlur,
    onKeyDown,
    editable = true,
    autofocus = true,
}: RichTextEditorProps) {
    const { addToast } = useUIStore()

    const editor = useEditor({
        extensions: [
            StarterKit,
            Image.configure({
                inline: true,
                allowBase64: true,
            }),
            TextAlign.configure({
                types: ['heading', 'paragraph'],
            }),
            TextStyle,
            Color,
            Underline,
        ],
        content,
        editable,
        autofocus,
        editorProps: {
            handleKeyDown: (view, event) => {
                if (onKeyDown) {
                    onKeyDown(event as unknown as KeyboardEvent)
                }
                // Return false to let TipTap handle the event too, unless we want to stop propagation
                // If Escape, we might want to stop propagation if parent handles it
                if (event.key === 'Escape') {
                    return false // Let parent handle it
                }
                return false
            },
            attributes: {
                class: 'prose prose-sm sm:prose-base focus:outline-none max-w-none min-h-[60px] p-2',
            },
        },
        onUpdate: ({ editor }) => {
            onUpdate(editor.getHTML())
        },
        onBlur: () => {
            if (onBlur) {
                onBlur()
            }
        },
    })

    // Update content if it changes externally (only when not editing or if forced)
    // Usually we don't want to reset content while user is typing
    useEffect(() => {
        if (editor && content !== editor.getHTML() && !editor.isFocused) {
            editor.commands.setContent(content)
        }
    }, [content, editor])

    // Cleanup
    useEffect(() => {
        return () => {
            editor?.destroy()
        }
    }, [editor])

    const handleImageUpload = async (file: File) => {
        if (!editor) return

        try {
            const uploadedFile = await uploadFile(file)
            const imageUrl = uploadedFile.path.startsWith('http')
                ? uploadedFile.path
                : `${import.meta.env.VITE_API_URL || 'http://localhost:3000'}${uploadedFile.path}`

            editor.chain().focus().setImage({ src: imageUrl }).run()

        } catch (error) {
            console.error('Failed to upload image', error)
            addToast({
                type: 'error',
                title: '上传失败',
                message: '图片上传失败，请重试',
            })
        }
    }

    return (
        <div className="flex flex-col w-full h-full border rounded-md overflow-hidden bg-white">
            {editable && <EditorToolbar editor={editor} onImageUpload={handleImageUpload} />}
            <EditorContent editor={editor} className="flex-1 overflow-auto" />
        </div>
    )
}
